import sympy as sp
t=sp.symbols('t')
e=1/(1+sp.cos(t))+1/(1-sp.cos(t))
opts={'A':2*sp.sin(t)**2,'B':2*sp.sec(t)**2,'C':2*sp.csc(t)**2,'D':2*sp.tan(t)**2}
d={k:sp.simplify(e-v) for k,v in opts.items()}
assert d['C']==0
for k in 'ABD':
    assert abs(float((e-opts[k]).subs(t,0.7)))>1e-6

